@@ -0,0 +1,34 @@
+// Sites (kitchens). Every location belongs to one site; batches belong to the
+// site of their location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Ids of the locations in a site, or of every location when `site` is undefined. */
+export function siteLocationIds(store, site) {
+  return new Set(store.data.locations.filter((l) => site === undefined || l.site === site).map((l) => l.id));
+}
+
+/** True when a location exists and is in `site` (any site when undefined). */
+export function locationInSite(store, location, site) {
+  return siteLocationIds(store, site).has(location);
+}
+
+/** Batches in a site's locations, or every batch when `site` is undefined. */
+export function siteBatches(store, site) {
+  if (site === undefined) return store.data.batches;
+  const ids = siteLocationIds(store, site);
+  return store.data.batches.filter((b) => ids.has(b.location));
+}
