--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,114 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 2 l of milk (item 2) into the annex fridge through an order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 2 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("the seed has two sites and the annex fridge", () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const a = await handle({ path: "/reports/stock-value" });
+  const b = await handle({ path: "/reports/stock-value", headers: { "X-Larder-Site": "main" } });
+  assert.deepEqual(a.body, b.body);
+  assert.ok(a.body.totalCents > 0);
+});
+
+test("batches and stock on hand only see the request's site", async () => {
+  const { handle } = app();
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  assert.equal((await handle({ path: "/items", headers: ANNEX })).body.find((i) => i.id === 2).onHand, 0);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).body.error.code, "unknown_batch");
+  const batch = await stockAnnex(handle);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.equal((await handle({ path: "/items/2", headers: ANNEX })).body.onHand, 2);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  const waste = await handle({ method: "POST", path: `/batches/${batch.id}/waste`, body: { qty: 1 } });
+  assert.equal(waste.status, 404);
+});
+
+test("receiving into another site's location is refused", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 2 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "AX-1", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const none = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(none.status, 409);
+  await stockAnnex(handle);
+  const before = JSON.stringify(store.data.batches.filter((b) => b.location !== "annex-fridge"));
+  // Bechamel needs milk, butter and flour; the annex has only milk.
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches.filter((b) => b.location !== "annex-fridge")), before);
+});
+
+test("alerts and the stock value report only see the request's site", async () => {
+  const { handle } = app();
+  const empty = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(empty.expiring, []);
+  assert.equal(empty.lowStock.length, 6);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+  const mainBefore = (await handle({ path: "/reports/stock-value" })).body.totalCents;
+  await stockAnnex(handle);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(!(await handle({ path: "/alerts" })).body.expiring.some((b) => b.lot === "AX-1"));
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 258);
+  assert.equal((await handle({ path: "/reports/stock-value" })).body.totalCents, mainBefore);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  const wrong = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "fridge" } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const batch = await stockAnnex(handle);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: batch.id, counted: 1.5 } });
+  const done = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(done.body.lines, [{ batchId: batch.id, expected: 2, counted: 1.5, diff: -0.5 }]);
+});
+
+test("items, recipes and dishes are shared", async () => {
+  const { handle } = app();
+  for (const path of ["/items/1/best-price", "/recipes/1/cost", "/dishes", "/suppliers"])
+    assert.deepEqual((await handle({ path, headers: ANNEX })).body, (await handle({ path })).body);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:annex:2026-10-28"));
+  assert.match(store.data.outbox.find((m) => m.key === "low:annex:2026-10-28").subject, /^Annex kitchen: 6 items/);
+});
